// ================== CẤU HÌNH — SỬA Ở ĐÂY ==================
const CONFIG = {
  WIDGET_SECRET: 'doi-chuoi-bi-mat-nay',   // phải khớp SECRET trong widget.html
  JIRA_BASE_URL: 'https://your-company.atlassian.net',
  JIRA_CUSTOMER_FIELD: '',   // vd 'cf[10050]' nếu ticket có custom field lưu email khách; trống = tìm full-text
  JIRA_PROJECTS: '',         // vd 'SUP,DEV'; trống = mọi project
  JIRA_DONE_LOOKBACK: '-7d', // vẫn hiện ticket đã Done nếu cập nhật trong khoảng này (để báo khách là đã xong)
  SUPABASE_URL: 'https://xxxxxxxx.supabase.co',
  GEMINI_MODEL: 'gemini-2.5-flash',
  EMBED_MODEL: 'gemini-embedding-001',
  EMBED_DIM: 768,
  SIMILAR_CASES: 4,
  MIN_SIMILARITY: 0.6,
  HISTORY_MESSAGES: 30,
  CACHE_TTL_HOURS: 24,       // draft cũ còn dùng lại được trong bao lâu
  MAX_TICKETS: 5,            // số ticket tối đa lấy comment
  COMMENTS_PER_TICKET: 6,    // số comment mới nhất mỗi ticket
  CS_COMMENT_AUTHORS: [],    // tên hiển thị Jira của team CS, vd ['Lan Nguyen', 'Minh Tran'] -> comment của họ không tính là cập nhật từ tech
  IGNORE_COMMENT_AUTHORS: ['Automation for Jira'], // bỏ qua comment bot
  ATTACHMENT_PROXY_URL: 'https://YOUR-N8N-DOMAIN/webhook/jira-attachment', // Production URL của workflow Attachment Proxy
  ATTACHMENT_SECRET: 'doi-chuoi-bi-mat-anh',   // phải giống hệt trong workflow Attachment Proxy
};
// ===========================================================
const q = $input.first().json.query || {};
if (CONFIG.WIDGET_SECRET && q.secret !== CONFIG.WIDGET_SECRET) throw new Error('Sai secret');
const action = q.action === 'generate' ? 'generate' : 'check';
if (!q.website_id || !q.session_id) throw new Error('Thiếu website_id hoặc session_id');

return [{ json: {
  config: CONFIG,
  action,
  website_id: String(q.website_id),
  session_id: String(q.session_id),
  operator_id: String(q.operator_id || ''),
  operator_name: String(q.operator_name || ''),
  force: q.force === '1',    // CS bấm "Soạn lại" -> bỏ qua cache
} }];

const base = $('Config & Validate').first().json;
const cfg = base.config;
const msgRes = $('Get Messages').first().json || {};
const msgs = (Array.isArray(msgRes.data) ? msgRes.data : []).slice().sort((a, b) => a.timestamp - b.timestamp);
const meta = ($('Get Conversation Meta').first().json || {}).data || {};
const BOT_MARK = '🤖';

function render(m) {
  if (m.type === 'text') return String(m.content ?? '');
  if (m.type === 'file') return `[Gửi file: ${m.content?.name || ''} ${m.content?.url || ''}]`;
  if (m.type === 'note') {
    const t = String(m.content ?? '');
    return t.startsWith(BOT_MARK) ? null : `[Ghi chú nội bộ] ${t}`;
  }
  if (m.type === 'event') return null;
  return `[${m.type}]`;
}

const lines = [];
for (const m of msgs) {
  const t = render(m);
  if (t === null) continue;
  const who = m.from === 'user' ? 'Khách' : `CS${m.user?.nickname ? ' (' + m.user.nickname + ')' : ''}`;
  lines.push(`${who}: ${t.slice(0, 1500)}`);
}

// Tin khách gửi liên tiếp từ lần CS trả lời gần nhất = phần chưa được trả lời
const real = msgs.filter(m => m.type !== 'note' && m.type !== 'event');
const unanswered = [];
for (let i = real.length - 1; i >= 0 && real[i].from === 'user'; i--) {
  const t = render(real[i]);
  if (t) unanswered.unshift(t);
}
const lastUser = [...real].reverse().find(m => m.from === 'user');
const lastOperator = [...real].reverse().find(m => m.from === 'operator');

// ----- JQL -----
const email = (meta.email || '').trim();
const custom = meta.data || {};
const keySet = new Set(String(custom.jira_keys || custom.jira_key || '')
  .split(/[\s,;]+/).filter(k => /^[A-Z][A-Z0-9_]+-\d+$/.test(k)));
// Dự phòng: đọc link Jira CS dán trong note của conversation
for (const m of msgs) {
  if (m.type !== 'note' || typeof m.content !== 'string') continue;
  for (const g of m.content.matchAll(/\/browse\/([A-Z][A-Z0-9_]+-\d+)/g)) keySet.add(g[1]);
}
const keys = [...keySet];
const ident = [];
if (keys.length) ident.push(`key in (${keys.join(',')})`);
if (email) {
  const e = email.replace(/"/g, '');
  ident.push(cfg.JIRA_CUSTOMER_FIELD ? `${cfg.JIRA_CUSTOMER_FIELD} ~ "${e}"` : `text ~ "\\"${e}\\""`);
}
ident.push(`text ~ "\\"${base.session_id}\\""`);
let jql = `(${ident.join(' OR ')}) AND (statusCategory != Done OR updated >= ${cfg.JIRA_DONE_LOOKBACK})`;
if (cfg.JIRA_PROJECTS) jql += ` AND project in (${cfg.JIRA_PROJECTS})`;
jql += ' ORDER BY updated DESC';

const recentUser = real.filter(m => m.from === 'user').slice(-8).map(render).filter(Boolean);
const focus = unanswered.length ? unanswered : recentUser.slice(-3);

return [{ json: {
  ...base,
  customer_email: email,
  customer_name: meta.nickname || '',
  customer_data: custom,
  history: lines.slice(-cfg.HISTORY_MESSAGES).join('\n'),
  unanswered,
  recent_user_messages: recentUser,
  needs_reply: unanswered.length > 0,
  last_customer_at: lastUser?.timestamp || null,
  last_operator_at: lastOperator?.timestamp || 0,
  last_user_fp: lastUser ? `${lastUser.timestamp}:${lastUser.fingerprint ?? ''}` : '',
  jql,
  search_text: `Vấn đề khách: ${focus.join(' / ')}`.slice(0, 6000),
} }];

const cfg = $('Config & Validate').first().json.config;
const res = $('Search Jira Tickets').first().json || {};
const issues = Array.isArray(res.issues) ? res.issues.slice(0, cfg.MAX_TICKETS) : [];
// Không có ticket vẫn trả 1 item để luồng chạy tiếp (node comment sẽ lỗi mềm và bị bỏ qua)
if (!issues.length) return [{ json: { key: null } }];
return issues.map(i => ({ json: { key: i.key } }));

const ctx = $('Prepare Context').first().json;
const cfg = ctx.config;
const res = $('Search Jira Tickets').first().json || {};
const issues = Array.isArray(res.issues) ? res.issues.slice(0, cfg.MAX_TICKETS) : [];

// Ghép kết quả comment (cùng thứ tự với Split Tickets)
const splitItems = $('Split Tickets').all().map(x => x.json);
const commentRes = $input.all().map(x => x.json);
const byKey = {};
splitItems.forEach((it, i) => { if (it.key) byKey[it.key] = commentRes[i] || {}; });

function adfToText(n) {
  if (!n) return '';
  if (typeof n === 'string') return n;
  if (n.type === 'text') return n.text || '';
  if (n.type === 'hardBreak') return '\n';
  if (n.type === 'mention') return n.attrs?.text || '';
  if (n.type === 'media' || n.type === 'mediaInline') return `[Ảnh: ${n.attrs?.alt || 'không tên'}]`;
  if (n.type === 'inlineCard' || n.type === 'blockCard') return n.attrs?.url || '';
  const inner = (n.content || []).map(adfToText).join('');
  if (n.type === 'codeBlock') return '```\n' + inner + '\n```\n';
  if (n.type === 'listItem') return '• ' + inner;
  return ['paragraph', 'heading', 'blockquote'].includes(n.type) ? inner + '\n' : inner;
}
// ---- HMAC-SHA256 thuần JS (Code node của n8n mặc định không cho require('crypto')) ----
function sha256(bytes) {
  const frac = (x) => ((x - Math.floor(x)) * 4294967296) >>> 0;
  const primes = []; for (let n = 2; primes.length < 64; n++) if (primes.every(p => n % p)) primes.push(n);
  const K = primes.map(p => frac(Math.cbrt(p)));
  const H = primes.slice(0, 8).map(p => frac(Math.sqrt(p)));
  const len = bytes.length, total = ((len + 9 + 63) >> 6) << 6;
  const buf = new Uint8Array(total); buf.set(bytes); buf[len] = 0x80;
  const dv = new DataView(buf.buffer);
  dv.setUint32(total - 4, (len * 8) >>> 0); dv.setUint32(total - 8, Math.floor(len / 536870912));
  const W = new Uint32Array(64), r = (x, n) => (x >>> n) | (x << (32 - n));
  for (let o = 0; o < total; o += 64) {
    for (let i = 0; i < 16; i++) W[i] = dv.getUint32(o + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = r(W[i - 15], 7) ^ r(W[i - 15], 18) ^ (W[i - 15] >>> 3);
      const s1 = r(W[i - 2], 17) ^ r(W[i - 2], 19) ^ (W[i - 2] >>> 10);
      W[i] = (W[i - 16] + s0 + W[i - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + W[i]) | 0;
      const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    [a, b, c, d, e, f, g, h].forEach((v, i) => { H[i] = (H[i] + v) >>> 0; });
  }
  const out = new Uint8Array(32); H.forEach((v, i) => new DataView(out.buffer).setUint32(i * 4, v)); return out;
}
const utf8 = (s) => Uint8Array.from(unescape(encodeURIComponent(String(s))), ch => ch.charCodeAt(0));
function hmacHex(key, msg) {
  let k = utf8(key); if (k.length > 64) k = sha256(k);
  const kp = new Uint8Array(64); kp.set(k);
  const inner = new Uint8Array(64 + utf8(msg).length); inner.set(kp.map(x => x ^ 0x36)); inner.set(utf8(msg), 64);
  const ih = sha256(inner);
  const outer = new Uint8Array(96); outer.set(kp.map(x => x ^ 0x5c)); outer.set(ih, 64);
  return [...sha256(outer)].map(x => x.toString(16).padStart(2, '0')).join('');
}

// ---- Tìm file đính kèm thuộc về 1 comment ----
function mediaAlts(n, acc = []) {
  if (!n || typeof n !== 'object') return acc;
  if ((n.type === 'media' || n.type === 'mediaInline') && n.attrs) acc.push(n.attrs.alt || '');
  (n.content || []).forEach(c => mediaAlts(c, acc));
  return acc;
}
function commentAttachments(c, attachments) {
  const ids = new Set();
  const html = String(c.renderedBody || '');
  for (const m of html.matchAll(/\/attachment\/(?:content\/|thumbnail\/)?(\d+)/g)) ids.add(m[1]);      // 1. link ảnh trong HTML
  for (const m of html.matchAll(/\/secure\/(?:attachment|thumbnail)\/(\d+)\//g)) ids.add(m[1]);
  const cMs = Date.parse(c.created || '') || 0;
  const alts = mediaAlts(c.body);
  for (const alt of alts.filter(Boolean)) {                                                          // 2. khớp tên file
    const cands = attachments.filter(a => a.filename === alt)
      .sort((x, y) => Math.abs(Date.parse(x.created) - cMs) - Math.abs(Date.parse(y.created) - cMs));
    if (cands.length) ids.add(String(cands[0].id));
  }
  if (alts.length > ids.size) {                                                                      // 3. cùng người, ±3 phút
    attachments.filter(a => a.author?.accountId && a.author.accountId === c.author?.accountId
      && Math.abs((Date.parse(a.created) || 0) - cMs) <= 180000).forEach(a => ids.add(String(a.id)));
  }
  return attachments.filter(a => ids.has(String(a.id)));
}
const isImage = a => /^image\//.test(a?.mimeType || '');
const proxyUrl = (cfg, id, thumb) => `${cfg.ATTACHMENT_PROXY_URL}?id=${id}${thumb ? '&thumb=1' : ''}&sig=${hmacHex(cfg.ATTACHMENT_SECRET, String(id))}`;
const kb = n => (n >= 1048576 ? (n / 1048576).toFixed(1) + ' MB' : Math.max(1, Math.round((n || 0) / 1024)) + ' KB');
const norm = v => String(v || '').toLowerCase();
const matchAny = (name, list) => (list || []).some(x => x && norm(name).includes(norm(x)));
const lastOp = Number(ctx.last_operator_at) || 0;   // lần cuối CS nhắn khách (ms)

const tickets = issues.map(i => {
  const f = i.fields || {};
  const cr = byKey[i.key] || {};
  const atts = Array.isArray(f.attachment) ? f.attachment : [];
  const comments = (Array.isArray(cr.comments) ? cr.comments : [])
    .filter(c => !matchAny(c.author?.displayName, cfg.IGNORE_COMMENT_AUTHORS))
    .map(c => {
      const author = c.author?.displayName || '?';
      const ms = Date.parse(c.created || '') || 0;
      return {
        id: String(c.id),
        author,
        role: matchAny(author, cfg.CS_COMMENT_AUTHORS) ? 'cs' : 'tech',
        created: c.created || '',
        created_ms: ms,
        is_new: lastOp ? ms > lastOp : true,
        public: c.jsdPublic === true,
        text: adfToText(c.body).replace(/\n{3,}/g, '\n\n').trim(),
        images: commentAttachments(c, atts).map(a => ({
          id: String(a.id), filename: a.filename, is_image: isImage(a), size: kb(a.size),
          url: proxyUrl(cfg, a.id), thumb: isImage(a) ? proxyUrl(cfg, a.id, true) : null,
        })),
      };
    })
    .sort((a, b) => a.created_ms - b.created_ms);   // cũ -> mới

  const statusMs = Date.parse(f.statuscategorychangedate || '') || 0;
  const newTech = comments.filter(c => c.is_new && c.role === 'tech');
  const last = comments[comments.length - 1];
  return {
    key: i.key,
    url: `${cfg.JIRA_BASE_URL}/browse/${i.key}`,
    summary: f.summary || '',
    status: f.status?.name || '?',
    status_category: f.status?.statusCategory?.key || '',
    priority: f.priority?.name || '',
    assignee: f.assignee?.displayName || '',
    updated: f.updated || '',
    status_changed_at: f.statuscategorychangedate || '',
    status_is_new: !!(lastOp && statusMs > lastOp),
    comments,
    new_tech_comments: newTech.length,
    latest_comment: last ? { author: last.author, role: last.role, created: last.created, is_new: last.is_new, preview: last.text.slice(0, 180), images: last.images } : null,
    comments_error: cr.error ? String(cr.error.message || cr.error).slice(0, 150) : null,
  };
});

// Cập nhật mới từ tech mà khách chưa được báo (chỉ tính khi CS đã từng nhắn trong hội thoại)
const newUpdates = lastOp ? tickets.flatMap(t => [
  ...(t.status_is_new ? [{ key: t.key, type: 'status', id: `${t.key}:status:${t.status}`, created: t.status_changed_at, preview: `Chuyển sang ${t.status}` }] : []),
  ...t.comments.filter(c => c.is_new && c.role === 'tech')
     .map(c => ({ key: t.key, type: 'comment', id: `${t.key}:${c.id}`, author: c.author, created: c.created, preview: c.text.slice(0, 160) })),
]) : [];

function fnv(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
}
const hashSrc = [ctx.session_id, ctx.operator_id, ctx.last_user_fp, ctx.unanswered.length, lastOp,
  ...tickets.map(t => `${t.key}:${t.status}:${t.comments.map(c => c.id).join('.')}`)].join('|');

return [{ json: {
  ...ctx,
  tickets,
  has_jira: tickets.length > 0,
  jira_error: res.error ? String(res.error.message || res.error).slice(0, 200) : null,
  has_new_tech_update: newUpdates.length > 0,
  new_updates: newUpdates,
  update_marker: newUpdates.length ? fnv(newUpdates.map(u => u.id).join('|')) : '',
  context_hash: fnv(hashSrc) + fnv([...hashSrc].reverse().join('')),
  cache_since: new Date(Date.now() - cfg.CACHE_TTL_HOURS * 3600 * 1000).toISOString(),
} }];

const ctx = $('Jira Status').first().json;
const rows = $('Lookup Cache').all().map(x => x.json)
  .filter(r => r && r.payload && typeof r.payload === 'object' && r.payload.draft);
const hit = rows[0] || null;
return [{ json: {
  ...ctx,
  has_cached_draft: !!hit,
  cached: hit ? hit.payload : null,
  cached_at: hit ? hit.created_at : null,
  cache_status: hit && !ctx.force ? 'hit' : 'miss',
} }];

const ctx = $('Jira Status').first().json;
const cfg = ctx.config;

// ----- case cũ -----
const cases = $('Search Similar Cases').all().map(x => x.json)
  .filter(c => c && c.summary && (c.similarity ?? 1) >= cfg.MIN_SIMILARITY).slice(0, cfg.SIMILAR_CASES);
const caseBlock = cases.length ? cases.map((c, i) =>
  `Case ${i + 1} (độ giống ${Number(c.similarity ?? 0).toFixed(2)}):\n  Vấn đề: ${c.summary}\n  Cách xử lý: ${c.resolution || '-'}\n  Tin CS đã gửi: ${(c.final_reply || '-').slice(0, 800)}`).join('\n\n')
  : '(chưa có case tương tự)';

// ----- hồ sơ CS -----
const profiles = $('Get Agent Profile').all().map(x => x.json).filter(p => p && p.crisp_user_id);
const p = profiles.find(x => x.crisp_user_id === ctx.operator_id)
  || profiles.find(x => x.crisp_user_id === 'default') || {};
const samples = (p.sample_messages || []).slice(0, 8).map(s => `  «${s}»`).join('\n');
const profileBlock = [
  `Tên CS: ${p.display_name || ctx.operator_name || 'CS'}`,
  `Xưng hô: CS tự xưng "${p.pronoun_self || 'mình'}", gọi khách là "${p.pronoun_customer || 'bạn'}"`,
  `Giọng văn: ${p.tone || 'thân thiện, lịch sự, ngắn gọn'}`,
  `Emoji: ${p.use_emoji ? 'được dùng, tiết chế' : 'không dùng'}`,
  p.signature ? `Ký tên cuối tin: ${p.signature}` : 'Không ký tên',
  p.style_notes ? `Ghi chú thêm: ${p.style_notes}` : '',
  samples ? `Tin mẫu CS này từng viết (bắt chước văn phong, KHÔNG copy nội dung):\n${samples}` : '',
].filter(Boolean).join('\n');

// ----- Chọn chế độ -----
// jira_update: khách không hỏi gì mới nhưng tech vừa có cập nhật -> soạn tin chủ động báo khách
// jira: khách đang chờ và có ticket -> trả lời dựa trên status + troubleshoot của tech
// summary: không có ticket -> tóm tắt chat và soạn phản hồi
const mode = !ctx.has_jira ? 'summary'
  : (ctx.unanswered.length === 0 && ctx.has_new_tech_update ? 'jira_update' : 'jira');

const ticketBlock = ctx.tickets.map(t => {
  const head = `- ${t.key} | ${t.summary} | Trạng thái: ${t.status} (${t.status_category})`
    + (t.status_is_new ? ' ← VỪA ĐỔI, khách chưa được báo' : '')
    + ` | Phụ trách: ${t.assignee || 'chưa gán'}`;
  const cm = t.comments.map(c => {
    const tags = [c.is_new ? 'MỚI' : 'CŨ', c.role === 'tech' ? 'TECH' : 'CS', c.public ? 'ĐÃ CÔNG KHAI CHO KHÁCH' : null].filter(Boolean).join('][');
    const body = c.text.slice(0, c.is_new ? 2000 : 500);
    return `    [${tags}] ${c.author} (${c.created.slice(0, 16).replace('T', ' ')}):\n      ${body.replace(/\n/g, '\n      ')}`;
  }).join('\n');
  return head + (cm ? `\n  Comment (cũ → mới):\n${cm}` : '\n  (chưa có comment)');
}).join('\n');

const TROUBLESHOOT = `Cách đọc comment của team tech (ưu tiên comment [MỚI][TECH], comment mới hơn thắng comment cũ hơn):
- Rút ra: (a) nguyên nhân/kết luận đã xác định, (b) cách khắc phục tạm (workaround) khách tự làm được, (c) thông tin/thao tác tech cần khách cung cấp (log, ảnh, video, bước tái hiện, thiết bị, thời điểm, ID đơn...), (d) bước tiếp theo và mốc thời gian NẾU tech nêu rõ.
- Chuyển thành lời dễ hiểu cho khách: bỏ thuật ngữ nội bộ, tên service, stack trace; không đổ lỗi, không nêu tên người.
- Tech cần thông tin từ khách → bản nháp phải hỏi đúng các thông tin đó, kèm hướng dẫn ngắn cách lấy nếu đơn giản.
- Có workaround → hướng dẫn khách từng bước ngắn gọn.
- Comment còn phỏng đoán, mâu thuẫn, hoặc chưa có kết luận → không khẳng định nguyên nhân; nói đang tiếp tục kiểm tra.
- Comment chỉ là trao đổi nội bộ (phân công, ping nhau, thảo luận ưu tiên) → bỏ qua.
- Không hứa ngày/giờ nếu tech không ghi rõ.`;

const task = mode === 'jira_update'
  ? `CHẾ ĐỘ CẬP NHẬT CHỦ ĐỘNG — khách chưa hỏi thêm, nhưng ticket có cập nhật mới (comment [MỚI][TECH] hoặc trạng thái vừa đổi) mà khách chưa được báo.
1. Tóm tắt vấn đề của khách trong 1 câu.
2. Soạn tin chủ động báo khách về tiến triển mới, dựa trên các cập nhật MỚI. Không lặp lại điều CS đã nói trong lịch sử chat.
3. Nếu cập nhật mới chỉ là trao đổi nội bộ không có gì đáng báo khách, nói rõ trong ticket_note và để draft là tin hỏi thăm/trấn an ngắn.

${TROUBLESHOOT}`
  : mode === 'jira'
  ? `CHẾ ĐỘ TRẢ LỜI THEO JIRA — khách đang chờ trả lời và có ticket liên quan.
1. Tóm tắt vấn đề của khách trong 1–2 câu.
2. Trả lời đúng điều khách vừa hỏi, lồng thông tin từ trạng thái ticket và troubleshoot của tech. Status done → báo đã xử lý, nhờ khách kiểm tra lại; đang xử lý → nêu tiến triển cụ thể nếu có; mới tạo → xác nhận đã ghi nhận.
