const ctx = $('Build Prompt').first().json;
const res = $input.first().json || {};
if (res.error) throw new Error('Gemini lỗi: ' + JSON.stringify(res.error).slice(0, 300));
const parts = res.candidates?.[0]?.content?.parts || [];
const raw = parts.filter(p => !p.thought).map(p => p.text || '').join('').trim();
if (!raw) throw new Error('Gemini không trả nội dung (finishReason=' + (res.candidates?.[0]?.finishReason || '?') + ')');

let out;
try { out = JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '')); }
catch (e) { out = { summary: '', draft: raw, missing_info: [], confidence: 'low' }; }
const s = v => (v == null ? '' : String(v).trim());

const TITLE = { jira: '🤖 GỢI Ý (theo Jira + troubleshoot)', jira_update: '🤖 GỢI Ý (báo cập nhật mới từ tech)', summary: '🤖 GỢI Ý (tóm tắt từ chat)' };
const tf = out.tech_findings && typeof out.tech_findings === 'object' ? out.tech_findings : {};
const techFindings = {
  root_cause: s(tf.root_cause), workaround: s(tf.workaround), next_step: s(tf.next_step),
  need_from_customer: Array.isArray(tf.need_from_customer) ? tf.need_from_customer.map(s).filter(Boolean) : [],
};
const L = [TITLE[ctx.mode] || '🤖 GỢI Ý', ''];
if (s(out.summary)) L.push(`📌 Vấn đề: ${s(out.summary)}${s(out.category) ? ' [' + s(out.category) + ']' : ''}`);
if (ctx.mode !== 'summary') {
  L.push('🎫 ' + ctx.tickets.map(t => `${t.key}: ${t.status}${t.new_tech_comments ? ` (+${t.new_tech_comments} cmt mới)` : ''}`).join(' | '));
  if (s(out.ticket_note)) L.push(`   → ${s(out.ticket_note)}`);
  if (techFindings.root_cause) L.push(`🔧 Nguyên nhân: ${techFindings.root_cause}`);
  if (techFindings.workaround) L.push(`🩹 Khắc phục tạm: ${techFindings.workaround}`);
  if (techFindings.need_from_customer.length) L.push(`📥 Tech cần từ khách: ${techFindings.need_from_customer.join('; ')}`);
  if (techFindings.next_step) L.push(`⏭ Bước tiếp: ${techFindings.next_step}`);
}
L.push('', '✉️ Bản nháp:', s(out.draft));
if (s(out.alternative)) L.push('', '✉️ Phương án khác:', s(out.alternative));
const missing = Array.isArray(out.missing_info) ? out.missing_info.filter(Boolean) : [];
if (missing.length) L.push('', `❓ Cần xác minh: ${missing.join('; ')}`);
if (ctx.mode === 'summary' && out.suggest_create_ticket) L.push('🛠 Nên tạo ticket Jira cho case này');

const response = {
  ok: true,
  action: 'generate',
  mode: ctx.mode,
  summary: s(out.summary),
  category: s(out.category),
  ticket_note: s(out.ticket_note),
  tech_findings: techFindings,
  draft: s(out.draft),
  alternative: s(out.alternative),
  missing_info: missing,
  suggest_create_ticket: !!out.suggest_create_ticket,
  confidence: s(out.confidence),
  tickets: ctx.tickets.map(t => ({ key: t.key, status: t.status, status_category: t.status_category, url: t.url, summary: t.summary, new_tech_comments: t.new_tech_comments })),
  updates_reported: ctx.new_updates.map(u => u.id),
  generated_at: new Date().toISOString(),
};

return [{ json: {
  response,
  context_hash: ctx.context_hash,
  ok: true,
  mode: ctx.mode,
  website_id: ctx.website_id,
  session_id: ctx.session_id,
  operator_id: ctx.operator_id,
  summary: s(out.summary),
  category: s(out.category),
  ticket_note: s(out.ticket_note),
  draft: s(out.draft),
  alternative: s(out.alternative),
  missing_info: missing,
  suggest_create_ticket: !!out.suggest_create_ticket,
  confidence: s(out.confidence),
  tickets: ctx.tickets.map(t => ({ key: t.key, status: t.status, status_category: t.status_category, url: t.url, summary: t.summary })),
  note_content: L.join('\n'),
  cases_used: ctx.cases_used,
  profile_used: ctx.profile_used,
  model: ctx.config.GEMINI_MODEL,
} }];
